#include "roast/ble_setup.hpp"
#include <cassert>
#include <cstring>
#include <algorithm>
int main(){using namespace roast::ble; SetupAuthorization a;a.observe(1,true,0);a.confirm(2);assert(!a.authorized(2));a.request(3);assert(a.pending());a.confirm(4);assert(a.authorized(4));assert(a.remaining(4)==120000);assert(!a.authorized(120004));a.request(120005);a.confirm(120006);a.observe(2,true,120007);assert(!a.authorized(120007));a.request(0xfffffff0);a.confirm(0xfffffff1);assert(a.authorized(20));a.close();assert(!a.pending());a.observe(3,true,0);a.request(0);a.observe(3,true,120000);assert(!a.pending());a.confirm(120001);assert(!a.authorized(120001));
 SetupAssembler r;uint8_t f[20];const char* s="1\nstate\n";size_t n=setupFrame(7,8,0,reinterpret_cast<const uint8_t*>(s),4,f,20);assert(!r.push(f,n,0));n=setupFrame(7,8,4,reinterpret_cast<const uint8_t*>(s)+4,4,f,20);assert(r.push(f,n,9999));assert(r.size()==8&&!std::memcmp(r.data(),s,8));r.clear();n=setupFrame(8,8,0,reinterpret_cast<const uint8_t*>(s),4,f,20);assert(!r.push(f,n,0));assert(!r.push(f,n,1));n=setupFrame(8,8,4,reinterpret_cast<const uint8_t*>(s)+4,4,f,20);assert(!r.push(f,n,2));n=setupFrame(9,8,0,reinterpret_cast<const uint8_t*>(s),4,f,20);assert(!r.push(f,n,0));n=setupFrame(9,8,4,reinterpret_cast<const uint8_t*>(s)+4,4,f,20);assert(!r.push(f,n,10000));f[4]=0;f[5]=16;assert(!r.push(f,n,10001));
 char large[kSetupMax+1];std::memset(large,'x',sizeof(large));SetupAssembler max;size_t at=0;while(at<kSetupMax){const auto count=std::min(size_t(12),kSetupMax-at);const auto length=setupFrame(65535,kSetupMax,at,reinterpret_cast<uint8_t*>(large)+at,count,f,sizeof(f));assert(max.push(f,length,1)==(at+count==kSetupMax));at+=count;}assert(max.size()==kSetupMax);assert(!setupFrame(1,4096,0,reinterpret_cast<uint8_t*>(large),12,f,sizeof(f)));
}
